import heapq

def topological_order(nodes, edges):
    node_set = set(nodes)
    indegree = {node: 0 for node in nodes}
    adj = {node: set() for node in nodes}

    for u, v in edges:
        if u in node_set and v in node_set and v not in adj[u]:
            adj[u].add(v)
            indegree[v] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        return []
    return result
